    },
    {
      "card_ids": ["C24"],
      "claim": "Verapamil, a dimethoxyphenyl basic amine drug, has oral bioavailability around 18-20% in normal subjects, at or below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Urapidil, a structurally distant piperazine drug, has high oral bioavailability (78%), but its scaffold is not transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tetrabenazine-like scaffold with a basic side chain; the closest analog tetrabenazine has very low oral bioavailability (~5%), and other moderately similar drugs (almorexant, verapamil) are at or below 20%. The evidence supports a low oral bioavailability prediction.",
